import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.DaCm-iTo.js";const g=JSON.parse('{"title":"EmakiStorage","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/storage/index.md","filePath":"en/modules/storage/index.md","lastUpdated":null}'),d={name:"en/modules/storage/index.md"};function i(n,e,r,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="emakistorage" tabindex="-1">EmakiStorage <a class="header-anchor" href="#emakistorage" aria-label="Permalink to &quot;EmakiStorage&quot;">​</a></h1><p>EmakiStorage is the GUI warehouse module of the Emaki series. It stores player items in logical slots where a single slot can hold a <code>long</code>-scale amount while preserving the original <code>ItemStack</code> in full (components, enchantments and PDC are all kept as-is).</p><p>The warehouse window is described by the <code>gui/storage_gui.yml</code> template, capacity comes from <code>config.yml</code> combined with permission tiers, command grants and paid purchases, and deposit/withdraw behaviour is exposed through CoreLib actions, a public API and Bukkit events.</p><h2 id="basic-information" tabindex="-1">Basic Information <a class="header-anchor" href="#basic-information" aria-label="Permalink to &quot;Basic Information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>1.0.6</code></td></tr><tr><td>API Jar</td><td><code>emaki-storage-api-1.0.6.jar</code></td></tr><tr><td>Main class</td><td><code>emaki.jiuwu.craft.storage.EmakiStoragePlugin</code></td></tr><tr><td>Main command</td><td><code>/emakistorage</code></td></tr><tr><td>Alias</td><td><code>/estorage</code></td></tr><tr><td>Required dependency</td><td>EmakiCoreLib</td></tr><tr><td>Optional dependency</td><td>PlaceholderAPI</td></tr><tr><td>Descriptor baseline</td><td><code>api-version: &quot;1.21.8&quot;</code>, <code>folia-supported: true</code></td></tr><tr><td>Java</td><td>Java 25</td></tr><tr><td>Main permissions</td><td><code>emakistorage.use</code> (default true), <code>emakistorage.unlock.purchase</code> (default true), <code>emakistorage.reload</code> (op), <code>emakistorage.debug</code> (op), <code>emakistorage.admin</code> (op)</td></tr></tbody></table><h2 id="feature-pages" tabindex="-1">Feature Pages <a class="header-anchor" href="#feature-pages" aria-label="Permalink to &quot;Feature Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Contents</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands and Permissions</a></td><td>Subcommands, permission nodes and examples for <code>/emakistorage</code> and <code>/estorage</code>.</td></tr><tr><td><a href="./configuration.html">Configuration</a></td><td>The <code>unlock</code>, <code>behavior</code>, <code>search</code>, <code>persistence</code> and <code>logging</code> keys of <code>config.yml</code>.</td></tr><tr><td><a href="./capacity.html">Capacity</a></td><td>The <code>capacity</code> section, the four capacity sources, the three-level <code>stackLimit</code> and the overflow policies.</td></tr><tr><td><a href="./gui.html">GUI and Display</a></td><td>The <code>gui</code> and <code>display</code> sections, the <code>gui/storage_gui.yml</code> template structure and click semantics.</td></tr><tr><td><a href="./unlock-costs.html">Unlock Costs</a></td><td>The tiers, per-slot pricing and payment ordering of <code>unlock_costs.yml</code>.</td></tr><tr><td><a href="./corelib-actions.html">CoreLib Actions</a></td><td>The 5 actions EmakiStorage registers into the CoreLib ActionRegistry.</td></tr><tr><td><a href="./api.html">API and Integration</a></td><td>Calling the warehouse through <code>emaki-storage-api</code> and the result model.</td></tr><tr><td><a href="./events.html">Event API</a></td><td>The <code>StorageDepositEvent</code>, <code>StorageWithdrawEvent</code> and <code>StorageUnlockEvent</code> Bukkit events.</td></tr><tr><td><a href="./placeholders.html">PlaceholderAPI Placeholders</a></td><td>The 10 placeholders of the <code>emakistorage</code> extension and their resolution constraints.</td></tr></tbody></table><h2 id="core-capabilities" tabindex="-1">Core Capabilities <a class="header-anchor" href="#core-capabilities" aria-label="Permalink to &quot;Core Capabilities&quot;">​</a></h2><ul><li><strong><code>long</code>-scale per-slot storage:</strong> one logical slot holds one kind of item, and its ceiling comes from the three-level <code>stackLimit</code> configuration rather than the vanilla 64/99 stack size.</li><li><strong>Original item preserved in full:</strong> deduplication uses full <code>ItemStack#equals</code> (components, enchantments and custom PDC all take part). No hash signature layer is introduced, so two items of the same material with different components are never merged into one entry.</li><li><strong>Slot count is the single source of truth for capacity:</strong> <code>effectiveSlots</code> is the sum of <code>base_slots</code>, the permission tier, command grants and paid purchases, then clamped. Page count is derived from it (<code>ceil(effectiveSlots / slots per page)</code>); there is no reverse derivation from a configured page count.</li><li><strong>Mixed deposit:</strong> clicking any display slot with a loaded cursor and using the fixed <code>deposit_slot</code> port both funnel into one transaction implementation. Capacity checks, the filter, event publication and log emission exist exactly once.</li><li><strong>1–99 occupancy rendering:</strong> with <code>display.amount_mode: percent</code>, the item <code>amount</code> field expresses occupancy as 1–99 and the exact figure goes into lore. The valid range of the <code>max_stack_size</code> component is exactly 1–99, so no packet trickery is involved.</li><li><strong>Search and sort:</strong> search is substring matching and never compiles a regular expression; sorting is an explicit &quot;tidy up&quot; action that rewrites entry order.</li><li><strong>Zero-loss shrinking:</strong> when lowered capacity leaves occupancy over the limit, four policies are available and none of them causes irreversible data loss. There is no <code>drop</code> or <code>delete</code> option.</li><li><strong>Write-only flow log:</strong> business logic never reads the log files, and the three admin operation kinds <code>ADMIN_SET</code> / <code>ADMIN_GIVE</code> / <code>ADMIN_CLEAR</code> are always recorded.</li></ul><h2 id="persistence-design" tabindex="-1">Persistence Design <a class="header-anchor" href="#persistence-design" aria-label="Permalink to &quot;Persistence Design&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Implementation</th></tr></thead><tbody><tr><td>Entry data</td><td>Single binary file <code>storage.dat</code>, file magic <code>EMSTOR</code>, format version <code>1</code>.</td></tr><tr><td>Write strategy</td><td><strong>Full rewrite</strong>, not append. Every save produces an already-compact file, so there is no compactor, no garbage-ratio bookkeeping and no dangling-id repair.</td></tr><tr><td>Write ordering</td><td>Write a sibling <code>.tmp</code> first, re-read and validate the record count, then replace atomically. A failed write keeps the previous file and removes the tmp.</td></tr><tr><td>Per-record framing</td><td>Each record is framed separately using Paper&#39;s <code>ItemStack#serializeAsBytes()</code> / <code>deserializeBytes(byte[])</code>, which carry <code>DataVersion</code> and run through the DataFixer on read.</td></tr><tr><td>Corruption isolation</td><td>Records that fail to decode are written to <code>corrupt/&lt;uuid&gt;-&lt;timestamp&gt;.dat</code> and the remaining records load normally.</td></tr><tr><td>Hand-editable data</td><td>Slot counts, <code>stackLimit</code> values and the sort mode live in <code>meta.yml</code> (text YAML). Entry payloads stay binary because YAML cannot express a full <code>ItemStack</code>.</td></tr></tbody></table><h2 id="file-structure" tabindex="-1">File Structure <a class="header-anchor" href="#file-structure" aria-label="Permalink to &quot;File Structure&quot;">​</a></h2><p>After the server runs, EmakiStorage mainly uses the following files:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiStorage/</span></span>
<span class="line"><span>├─ config.yml</span></span>
<span class="line"><span>├─ unlock_costs.yml</span></span>
<span class="line"><span>├─ gui/</span></span>
<span class="line"><span>│  └─ storage_gui.yml</span></span>
<span class="line"><span>├─ lang/</span></span>
<span class="line"><span>│  ├─ zh_CN.yml</span></span>
<span class="line"><span>│  └─ en_US.yml</span></span>
<span class="line"><span>├─ data/</span></span>
<span class="line"><span>│  └─ &lt;uuid&gt;/</span></span>
<span class="line"><span>│     ├─ storage.dat</span></span>
<span class="line"><span>│     └─ meta.yml</span></span>
<span class="line"><span>├─ logs/</span></span>
<span class="line"><span>│  └─ &lt;uuid&gt;/</span></span>
<span class="line"><span>│     └─ &lt;yyyy-MM-dd&gt;.log</span></span>
<span class="line"><span>├─ corrupt/</span></span>
<span class="line"><span>└─ exports/</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Path</th><th>Description</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td>Main configuration: GUI, capacity, unlock/overflow, display, behaviour, search, persistence, logging.</td></tr><tr><td><code>unlock_costs.yml</code></td><td>Paid expansion tiers. A business data file, released only when missing; version upgrades never overwrite admin content.</td></tr><tr><td><code>gui/storage_gui.yml</code></td><td>Warehouse window template. The function row only declares <code>offset</code>; slot numbers are derived from <code>gui.storage_rows</code>.</td></tr><tr><td><code>lang/*.yml</code></td><td>GUI, command, unlock and console message text.</td></tr><tr><td><code>data/&lt;uuid&gt;/storage.dat</code></td><td>That player&#39;s entry data, binary, rewritten in full.</td></tr><tr><td><code>data/&lt;uuid&gt;/meta.yml</code></td><td>That player&#39;s slot counts, <code>stackLimit</code> values and sort mode; hand-editable.</td></tr><tr><td><code>logs/&lt;uuid&gt;/&lt;yyyy-MM-dd&gt;.log</code></td><td>Flow log, one directory per player and one file per day, write-only.</td></tr><tr><td><code>corrupt/</code></td><td>Quarantine directory for records that failed to decode.</td></tr><tr><td><code>exports/</code></td><td>Readable YAML dumps produced by <code>/estorage export</code>.</td></tr></tbody></table><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><ol><li>Place <code>EmakiCoreLib-*.jar</code> and <code>EmakiStorage-*.jar</code> into the server&#39;s <code>plugins/</code>.</li><li>Do not place <code>emaki-storage-api-*.jar</code> into <code>plugins/</code>; the API Jar is a compile dependency for developers only.</li><li>After the first start, review <code>plugins/EmakiStorage/config.yml</code> and <code>unlock_costs.yml</code>.</li><li>Open your own warehouse:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/estorage</span></span></code></pre></div><ol start="5"><li>After editing configuration, reload config, language and GUI templates:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/estorage reload</span></span></code></pre></div><ol start="6"><li>Grant slots to an online player and inspect the capacity breakdown:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/estorage slot grant Steve 10</span></span>
<span class="line"><span>/estorage info Steve</span></span></code></pre></div><h2 id="usage-notes" tabindex="-1">Usage Notes <a class="header-anchor" href="#usage-notes" aria-label="Permalink to &quot;Usage Notes&quot;">​</a></h2><ul><li>Setting <code>gui.deposit_feedback</code> to <code>none</code> is not recommended. Under mixed deposit an item lands where the entry order puts it, possibly on another page; without feedback the player will believe the item vanished.</li><li><code>emakistorage.slots.&lt;n&gt;</code> and <code>emakistorage.stacklimit.&lt;n&gt;</code> take the highest matching tier and <strong>do not support wildcards</strong>.</li><li>Lowering <code>capacity.base_slots</code> never consumes slots a player was granted or purchased; the three sources are persisted separately.</li><li>Overflow state is not persisted. It is derived from capacity versus occupancy and recomputed on login, reload, permission change and command grant.</li><li>Write-type admin commands require the target player to be online, see <a href="./commands.html">Commands and Permissions</a>.</li></ul>`,24)])])}const u=t(d,[["render",i]]);export{g as __pageData,u as default};
